const listNotificationDeliveries = `-- name: ListNotificationDeliveries :many
SELECT dl.id, dl.uuid, dl.channel, dl.attempt_no, dl.provider, dl.provider_ref, dl.recipient_masked,
    dl.subject, dl.status, dl.error, dl.sent_at, dl.finished_at, dl.created_at,
    d.uuid AS dispatch_uuid, d.event_code, d.audience, d.ref_type, d.ref_uuid, d.status AS dispatch_status, d.test,
    COALESCE(c.uuid, '00000000-0000-0000-0000-000000000000'::uuid)::uuid AS customer_uuid,
    COALESCE(NULLIF(c.company_title, ''), TRIM(COALESCE(c.first_name, '') || ' ' || COALESCE(c.last_name, '')), '')::text AS customer_name,
    COALESCE(u.uuid, '00000000-0000-0000-0000-000000000000'::uuid)::uuid AS user_uuid,
    TRIM(COALESCE(u.name, '') || ' ' || COALESCE(u.surname, ''))::text AS user_name,
    COUNT(*) OVER ()::bigint AS total_count
FROM notification_deliveries dl
JOIN notification_dispatches d ON d.organization_id = dl.organization_id AND d.id = dl.dispatch_id
LEFT JOIN customers c ON c.organization_id = d.organization_id AND c.id = d.customer_id
LEFT JOIN users u ON u.id = d.user_id
WHERE dl.organization_id = $1
  AND d.organization_id = $1
  AND ($2::text[] IS NULL OR dl.channel = ANY($2::text[]))
  AND ($3::text[] IS NULL OR dl.status = ANY($3::text[]))
  AND ($4::text[] IS NULL OR d.event_code = ANY($4::text[]))
  AND ($5::text[] IS NULL OR d.audience = ANY($5::text[]))
  AND ($6::timestamptz IS NULL OR dl.created_at >= $6::timestamptz)
  AND ($7::timestamptz IS NULL OR dl.created_at < $7::timestamptz)
  AND (
    $8::text IS NULL
    OR dl.recipient_masked ILIKE '%' || $8 || '%'
    OR dl.subject ILIKE '%' || $8 || '%'
    OR dl.provider_ref ILIKE '%' || $8 || '%'
    OR c.first_name ILIKE '%' || $8 || '%'
    OR c.last_name ILIKE '%' || $8 || '%'
    OR c.company_title ILIKE '%' || $8 || '%'
    OR u.name ILIKE '%' || $8 || '%'
    OR u.surname ILIKE '%' || $8 || '%'
  )
ORDER BY
  CASE WHEN $9::text = 'created_at' AND NOT $10::boolean THEN dl.created_at END ASC,
  CASE WHEN $9::text = 'created_at' AND $10::boolean THEN dl.created_at END DESC,
  CASE WHEN $9::text = 'channel' AND NOT $10::boolean THEN dl.channel END ASC,
  CASE WHEN $9::text = 'channel' AND $10::boolean THEN dl.channel END DESC,
  CASE WHEN $9::text = 'status' AND NOT $10::boolean THEN dl.status END ASC,
  CASE WHEN $9::text = 'status' AND $10::boolean THEN dl.status END DESC,
  CASE WHEN $9::text = 'event_code' AND NOT $10::boolean THEN d.event_code END ASC,
  CASE WHEN $9::text = 'event_code' AND $10::boolean THEN d.event_code END DESC,
  dl.created_at DESC, dl.id DESC
LIMIT $12 OFFSET $11
`

